    "@types/react-dom": "^19.0.4",
    "@vitejs/plugin-react": "^4.3.4",
    "typescript": "^5.8.2",
    "vite": "^6.2.2"
  }
}

{
  "compilerOptions": {
    "target": "ES2022",
    "lib": ["ES2023"],
    "module": "ESNext",
    "skipLibCheck": true,
    "moduleResolution": "Bundler",
    "strict": true,
    "noEmit": true
  },
  "include": ["vite.config.ts"]
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

export default defineConfig({
  plugins: [react()],
  server: {
    host: "0.0.0.0",
    port: 5173,
  },
  preview: {
    host: "0.0.0.0",
    port: 5173,
  },
});

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { App } from "./App";
import "./styles.css";

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

import { useEffect, useState } from "react";
import { ROSS_VERSION } from "@ross/shared";

type Health = { ok: boolean; service: string; version?: string };

const apiBase = import.meta.env.VITE_API_URL ?? "http://localhost:3001";

export function App() {
  const [apiHealth, setApiHealth] = useState<Health | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch(`${apiBase}/health`)
      .then(async (res) => {
        if (!res.ok) throw new Error(`API ${res.status}`);
        return res.json() as Promise<Health>;
      })
      .then((data) => {
        if (!cancelled) setApiHealth(data);
      })
      .catch((err: unknown) => {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "API unreachable");
        }
      });
    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <main className="shell">
      <header>
        <p className="eyebrow">Agentic Cinema · Parallel track</p>
        <h1>Ross</h1>
        <p className="tagline">
          Script continuity + real-world fact checks for the writers&apos; room.
        </p>
      </header>

      <section className="card">
        <h2>Status</h2>
        <dl>
          <div>
            <dt>Package</dt>
            <dd>v{ROSS_VERSION}</dd>
          </div>
          <div>
            <dt>API</dt>
            <dd>
              {error && <span className="bad">{error}</span>}
              {!error && !apiHealth && <span className="muted">checking…</span>}
              {apiHealth?.ok && (
                <span className="ok">
                  {apiHealth.service} ok
                  {apiHealth.version ? ` · v${apiHealth.version}` : ""}
                </span>
              )}
            </dd>
          </div>
          <div>
            <dt>Endpoint</dt>
            <dd className="mono">{apiBase}/health</dd>
          </div>
        </dl>
      </section>

      <p className="foot">Module 0 scaffold — upload &amp; analysis land next.</p>
    </main>
  );
}

:root {
  color-scheme: dark;
  --bg: #0c0f14;
  --card: #141a22;
  --text: #e8eef7;
  --muted: #8b98a8;
  --accent: #6ee7b7;
  --bad: #f87171;
  --border: #243041;
  font-family: "IBM Plex Sans", "Segoe UI", system-ui, sans-serif;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(ellipse 80% 50% at 20% -10%, #1a3a2f 0%, transparent 55%),
    var(--bg);
}

.shell {
  max-width: 40rem;
  margin: 0 auto;
  padding: 4rem 1.5rem;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.75rem;
  color: var(--accent);
  margin: 0 0 0.5rem;
}

h1 {
  font-size: 3rem;
  letter-spacing: -0.03em;
  margin: 0 0 0.5rem;
}

.tagline {
  color: var(--muted);
  margin: 0 0 2rem;
  font-size: 1.05rem;
}

.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem 1.5rem;
}

.card h2 {
  margin: 0 0 1rem;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  font-weight: 600;
}

dl {
  margin: 0;
  display: grid;
  gap: 0.75rem;
}

dl > div {
  display: grid;
  grid-template-columns: 6rem 1fr;
  gap: 0.75rem;
  align-items: baseline;
}

dt {
  color: var(--muted);
  font-size: 0.85rem;
}

dd {
  margin: 0;
}

.ok {
  color: var(--accent);
}

.bad {
  color: var(--bad);
}

.muted {
  color: var(--muted);
}

.mono {
  font-family: "IBM Plex Mono", ui-monospace, monospace;
  font-size: 0.85rem;
  word-break: break-all;
}

.foot {
  margin-top: 2rem;
  color: var(--muted);
  font-size: 0.9rem;
}

.vite-env.d.ts {
  display: none;
}

/// <reference types="vite/client" />

interface ImportMetaEnv {
  readonly VITE_API_URL?: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}

server {
    listen 5173;
    server_name _;
    root /usr/share/nginx/html;
    index index.html;

    location / {
        try_files $uri $uri/ /index.html;
    }
}

.PHONY: up down logs health smoke smoke-parallel smoke-gemini install

up:
	docker compose up --build -d

down:
	docker compose down

logs:
	docker compose logs -f --tail=200

health:
	@curl -sf http://localhost:3001/health | tee /dev/stderr | grep -q '"ok":true'
	@echo ""
	@curl -sf http://localhost:8000/health | tee /dev/stderr | grep -q '"ok":true'
	@echo ""
	@echo "health ok"

install:
	pnpm install
	cd apps/agent && python3 -m venv .venv && .venv/bin/pip install -r requirements.txt

smoke: smoke-parallel smoke-gemini

smoke-parallel:
	@test -f .env || (echo "missing .env — cp .env.example .env"; exit 1)
	@cd apps/agent && \
		(test -x .venv/bin/python || (python3 -m venv .venv && .venv/bin/pip install -r requirements.txt)) && \
		set -a && . ../../.env && set +a && \
		../../scripts/run-smoke.sh parallel

smoke-gemini:
	@test -f .env || (echo "missing .env — cp .env.example .env"; exit 1)
	@cd apps/agent && \
		(test -x .venv/bin/python || (python3 -m venv .venv && .venv/bin/pip install -r requirements.txt)) && \
		set -a && . ../../.env && set +a && \
		../../scripts/run-smoke.sh gemini

