import { z } from "zod";

// ── Character ──

export const CharacterSchema = z.object({
  id: z.string().uuid(),
  scriptId: z.string().uuid(),
  name: z.string().min(1),
  aliases: z.array(z.string()).default([]),
});

export type Character = z.infer<typeof CharacterSchema>;

// ── Line ──

export const LineTypeSchema = z.enum([
  "dialogue",
  "action",
  "direction",
  "parenthetical",
  "transition",
]);

export type LineType = z.infer<typeof LineTypeSchema>;

export const LineSchema = z.object({
  id: z.string().uuid(),
  sceneId: z.string().uuid(),
  type: LineTypeSchema,
  characterId: z.string().uuid().nullable(),
  text: z.string().min(1),
  sceneHeading: z.string(),
});

export type Line = z.infer<typeof LineSchema>;

// ── Scene ──

export const SceneSchema = z.object({
  id: z.string().uuid(),
  scriptId: z.string().uuid(),
  number: z.number().int().nonnegative(),
  heading: z.string().min(1),
  location: z.string().nullable(),
  timeOfDay: z.enum(["INT", "EXT"]).nullable(),
  lines: z.array(LineSchema).default([]),
  characterIds: z.array(z.string().uuid()).default([]),
});

export type Scene = z.infer<typeof SceneSchema>;

// ── Script ──

export const ScriptFormatSchema = z.enum(["plaintext", "fountain"]);

export type ScriptFormat = z.infer<typeof ScriptFormatSchema>;

export const ScriptSchema = z.object({
  id: z.string().uuid(),
  title: z.string().min(1),
  rawText: z.string(),
  format: ScriptFormatSchema,
  scenes: z.array(SceneSchema).default([]),
  characters: z.array(CharacterSchema).default([]),
  uploadedAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});

export type Script = z.infer<typeof ScriptSchema>;

import { z } from "zod";

// ── Enums ──

export const IssueTypeSchema = z.enum([
  "continuity_prop",
  "continuity_wardrobe",
  "continuity_injury",
  "timeline",
  "geography",
  "character_knowledge",
  "external_fact",
  "ambiguous",
  "unverifiable",
]);

export type IssueType = z.infer<typeof IssueTypeSchema>;

export const SeveritySchema = z.enum(["critical", "high", "medium", "low"]);

export type Severity = z.infer<typeof SeveritySchema>;

export const IssueStatusSchema = z.enum([
  "open",
  "investigating",
  "confirmed",
  "dismissed",
  "resolved",
]);

export type IssueStatus = z.infer<typeof IssueStatusSchema>;

// ── Source ──

export const SourceSchema = z.object({
  url: z.string().url(),
  title: z.string().min(1),
  snippet: z.string(),
  supportsVerdict: z.boolean(),
  retrievedAt: z.string().datetime(),
});

export type Source = z.infer<typeof SourceSchema>;

// ── Source Conflict ──

export const SourceConflictSchema = z.object({
  supportingCount: z.number().int().nonnegative(),
  disputingCount: z.number().int().nonnegative(),
  summary: z.string().min(1),
});

export type SourceConflict = z.infer<typeof SourceConflictSchema>;

// ── Issue ──

export const IssueSchema = z.object({
  id: z.string().uuid(),
  scriptId: z.string().uuid(),
  type: IssueTypeSchema,
  severity: SeveritySchema,
  confidence: z.number().min(0).max(1),
  status: IssueStatusSchema,

  title: z.string().min(1),
  description: z.string().min(1),
  evidence: z.string(),

  sceneIds: z.array(z.string().uuid()).default([]),
  characterIds: z.array(z.string().uuid()).default([]),
  entityName: z.string().nullable(),

  sources: z.array(SourceSchema).default([]),
  sourceConflict: SourceConflictSchema.nullable(),

  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
  resolvedAt: z.string().datetime().nullable(),
  dismissedReason: z.string().nullable(),
  recheckCount: z.number().int().nonnegative().default(0),
  lastRecheckAt: z.string().datetime().nullable(),
});

export type Issue = z.infer<typeof IssueSchema>;

// ── Issue lifecycle helpers ──

export const VALID_STATUS_TRANSITIONS: Record<IssueStatus, IssueStatus[]> = {
  open: ["investigating"],
  investigating: ["confirmed", "dismissed", "open"],
  confirmed: ["resolved", "open"],
  dismissed: ["open"],
  resolved: ["open"],
};

export function isValidTransition(from: IssueStatus, to: IssueStatus): boolean {
  return VALID_STATUS_TRANSITIONS[from]?.includes(to) ?? false;
}

// ── Severity ordering (highest first) ──

const SEVERITY_ORDER: Record<Severity, number> = {
  critical: 0,
  high: 1,
  medium: 2,
  low: 3,
};

export function compareSeverity(a: Severity, b: Severity): number {
  return SEVERITY_ORDER[a] - SEVERITY_ORDER[b];
}

import { z } from "zod";
import { ScriptSchema } from "./script.js";
import { IssueSchema, IssueStatusSchema } from "./issue.js";

// ── Upload Script ──

export const UploadScriptRequestSchema = z.object({
  title: z.string().min(1).optional(),
  content: z.string().min(1),
  format: z.enum(["plaintext", "fountain"]).default("plaintext"),
});

export type UploadScriptRequest = z.infer<typeof UploadScriptRequestSchema>;

export const UploadScriptResponseSchema = z.object({
  script: ScriptSchema,
});

export type UploadScriptResponse = z.infer<typeof UploadScriptResponseSchema>;

// ── Get Script ──

export const GetScriptResponseSchema = z.object({
  script: ScriptSchema,
});

export type GetScriptResponse = z.infer<typeof GetScriptResponseSchema>;

// ── List Issues ──

export const ListIssuesQuerySchema = z.object({
  status: IssueStatusSchema.optional(),
  severity: z.enum(["critical", "high", "medium", "low"]).optional(),
  type: z
    .enum([
      "continuity_prop",
      "continuity_wardrobe",
      "continuity_injury",
      "timeline",
      "geography",
      "character_knowledge",
      "external_fact",
      "ambiguous",
      "unverifiable",
    ])
    .optional(),
});

export type ListIssuesQuery = z.infer<typeof ListIssuesQuerySchema>;

export const ListIssuesResponseSchema = z.object({
  issues: z.array(IssueSchema),
  total: z.number().int().nonnegative(),
});

export type ListIssuesResponse = z.infer<typeof ListIssuesResponseSchema>;

// ── Update Issue ──

export const UpdateIssueRequestSchema = z.object({
  status: IssueStatusSchema.optional(),
  dismissedReason: z.string().nullable().optional(),
});

export type UpdateIssueRequest = z.infer<typeof UpdateIssueRequestSchema>;

export const UpdateIssueResponseSchema = z.object({
  issue: IssueSchema,
});

export type UpdateIssueResponse = z.infer<typeof UpdateIssueResponseSchema>;

// ── Analyze Script ──

export const AnalyzeRequestSchema = z.object({
  mode: z.enum(["full", "partial"]).default("full"),
  sceneIds: z.array(z.string().uuid()).optional(),
});

export type AnalyzeRequest = z.infer<typeof AnalyzeRequestSchema>;

export const JobStatusSchema = z.enum([
  "queued",
  "running",
  "completed",
  "failed",
]);

export type JobStatus = z.infer<typeof JobStatusSchema>;

export const AnalyzeResponseSchema = z.object({
  jobId: z.string().uuid(),
  status: JobStatusSchema,
});

export type AnalyzeResponse = z.infer<typeof AnalyzeResponseSchema>;

// ── Job Status ──

export const JobStatusResponseSchema = z.object({
  jobId: z.string().uuid(),
  status: JobStatusSchema,
  progress: z.number().min(0).max(100).nullable(),
  error: z.string().nullable(),
});

export type JobStatusResponse = z.infer<typeof JobStatusResponseSchema>;

// ── Recheck ──

export const RecheckRequestSchema = z.object({
  sceneIds: z.array(z.string().uuid()).min(1),
});

export type RecheckRequest = z.infer<typeof RecheckRequestSchema>;

export const RecheckResponseSchema = z.object({
  jobId: z.string().uuid(),
  status: JobStatusSchema,
});

export type RecheckResponse = z.infer<typeof RecheckResponseSchema>;

import { z } from "zod";
import { JobStatusSchema } from "./api.js";

export type JobStatus = z.infer<typeof JobStatusSchema>;

export const AnalysisJobSchema = z.object({
  id: z.string().uuid(),
  scriptId: z.string().uuid(),
  status: JobStatusSchema,
  mode: z.enum(["full", "partial"]),
  sceneIds: z.array(z.string().uuid()),
  progress: z.number().min(0).max(100).nullable(),
  error: z.string().nullable(),
  createdAt: z.string().datetime(),
  startedAt: z.string().datetime().nullable(),
  completedAt: z.string().datetime().nullable(),
});

export type AnalysisJob = z.infer<typeof AnalysisJobSchema>;

export const ROSS_VERSION = "0.0.0" as const;

export const MAX_SCRIPT_CHARS = 500_000 as const;
export const MAX_SCENES_PER_SCRIPT = 500 as const;
export const MAX_LINES_PER_SCENE = 200 as const;
export const MAX_ISSUES_PER_SCRIPT = 1_000 as const;

export const CONFIDENCE_THRESHOLD_HIGH = 0.8 as const;
export const CONFIDENCE_THRESHOLD_MEDIUM = 0.5 as const;
export const CONFIDENCE_THRESHOLD_LOW = 0.3 as const;

export type HealthStatus = {
  ok: true;
  service: "api" | "agent" | "web";
  version?: string;
};

import { serve } from "@hono/node-server";
import { Hono } from "hono";
