              )}
            </dd>
          </div>
          <div>
            <dt>Endpoint</dt>
            <dd className="mono">{apiBase}/health</dd>
          </div>
        </dl>
      </section>

      <p className="foot">Module 1 contracts loaded — upload &amp; analysis land next.</p>
    </main>
  );
}

